const reviewableBooking = `-- name: ReviewableBooking :one
SELECT b.id FROM ` + "`" + `telemed_bookings` + "`" + ` b
WHERE b.user_id = ? AND b.doctor_id = ? AND b.status = 'completed'
  AND NOT EXISTS (SELECT 1 FROM ` + "`" + `telemed_reviews` + "`" + ` r WHERE r.booking_id = b.id)
ORDER BY b.starts_at ASC, b.id ASC
LIMIT 1
`

type ReviewableBookingParams struct {
	UserID   uint64
	DoctorID uint64
}

// The user's oldest completed visit with the doctor that has no review yet.
func (q *Queries) ReviewableBooking(ctx context.Context, arg ReviewableBookingParams) (uint64, error) {
	row := q.db.QueryRowContext(ctx, reviewableBooking, arg.UserID, arg.DoctorID)
	var id uint64
	err := row.Scan(&id)
	return id, err
}

