const upsertConsent = `-- name: UpsertConsent :exec
INSERT INTO ` + "`" + `telemed_booking_consents` + "`" + ` (booking_id, scope, granted_at, revoked_at, created_at, updated_at)
VALUES (?, ?, ?, NULL, ?, ?)
ON DUPLICATE KEY UPDATE
  granted_at = IF(revoked_at IS NULL, granted_at, VALUES(granted_at)),
  revoked_at = NULL,
  updated_at = VALUES(updated_at)
`

type UpsertConsentParams struct {
	BookingID uint64
	Scope     string
	GrantedAt time.Time
	Stamp     sql.NullTime
}

// Grant (again): a revoked scope becomes active with a fresh granted_at.
func (q *Queries) UpsertConsent(ctx context.Context, arg UpsertConsentParams) error {
	_, err := q.db.ExecContext(ctx, upsertConsent,
		arg.BookingID,
		arg.Scope,
		arg.GrantedAt,
		arg.Stamp,
		arg.Stamp,
	)
	return err
}
